126	static int configure_alsa_capture(snd_pcm_t* pcm, snd_pcm_format_t format,
127	    unsigned int sample_rate, unsigned int channels)
128	{
129	    snd_pcm_hw_params_t* hw;
130	    snd_pcm_sw_params_t* sw;
131	    snd_pcm_uframes_t period_frames = sample_rate / 10;
132	    snd_pcm_uframes_t buffer_frames;
133	    int ret;
134	
135	    if (period_frames == 0) {
136	        period_frames = 256;
137	    }
138	
139	    buffer_frames = period_frames * 4;
140	
141	    snd_pcm_hw_params_alloca(&hw);
142	    ret = snd_vela_pcm_hw_params_any(pcm, hw);
143	    if (ret < 0) {
144	        return ret;
145	    }
146	
147	    ret = snd_vela_pcm_hw_params_set_access(pcm, hw,
148	        SND_PCM_ACCESS_RW_INTERLEAVED);
149	    if (ret < 0) {
150	        return ret;
151	    }
152	
153	    ret = snd_vela_pcm_hw_params_set_format(pcm, hw, format);
154	    if (ret < 0) {
155	        return ret;
156	    }
157	
158	    ret = snd_vela_pcm_hw_params_set_channels(pcm, hw, channels);
159	    if (ret < 0) {
160	        return ret;
161	    }
162	
163	    ret = snd_vela_pcm_hw_params_set_rate(pcm, hw, sample_rate, 0);
164	    if (ret < 0) {
165	        return ret;
166	    }
167	
168	    ret = snd_vela_pcm_hw_params_set_period_size(pcm, hw,
169	        period_frames, 0);
170	    if (ret < 0) {
171	        return ret;
172	    }
173	
174	    ret = snd_vela_pcm_hw_params_set_buffer_size(pcm, hw,
175	        buffer_frames);
176	    if (ret < 0) {
177	        return ret;
178	    }
179	
180	    ret = snd_vela_pcm_hw_params(pcm, hw);
181	    if (ret < 0) {
182	        return ret;
183	    }
184	
185	    snd_pcm_sw_params_alloca(&sw);
186	    ret = snd_vela_pcm_sw_params_current(pcm, sw);
187	    if (ret < 0) {
188	        return ret;
189	    }
190	
191	    ret = snd_vela_pcm_sw_params_set_start_threshold(pcm, sw, 1);
192	    if (ret < 0) {
193	        return ret;
194	    }
195	
196	    ret = snd_vela_pcm_sw_params_set_stop_threshold(pcm, sw, buffer_frames);
197	    if (ret < 0) {
198	        return ret;
199	    }
200	
201	    ret = snd_vela_pcm_sw_params_set_avail_min(pcm, sw, period_frames);
202	    if (ret < 0) {
203	        return ret;
204	    }
205	
206	    return snd_vela_pcm_sw_params(pcm, sw);
207	}
