415	int audio_capture_start(audio_capture_t* cap)
416	{
417	    if (!cap) {
418	        return -EINVAL;
419	    }
420	
421	    switch (cap->backend) {
422	    case AUDIO_CAPTURE_BACKEND_ALSA:
423	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
424	        if (!cap->handle.pcm) {
425	            return -EINVAL;
426	        }
427	
428	        if (cap->started) {
429	            return 0;
430	        }
431	
432	        if (snd_vela_pcm_prepare(cap->handle.pcm) < 0) {
433	            syslog(LOG_ERR, "[%s] ALSA prepare failed\n", TAG);
434	            return -EIO;
435	        }
