608	#ifdef CONFIG_AUDIO_MULTI_SESSION
609	static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
610	                            FAR void *session,
611	                            FAR const struct audio_caps_s *caps)
612	#else
613	static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
614	                            FAR const struct audio_caps_s *caps)
615	#endif
616	{
617	  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
618	
619	#ifdef CONFIG_AUDIO_MULTI_SESSION
620	  (void)session;
621	#endif
622	
623	  switch (caps->ac_type)
624	    {
625	      case AUDIO_TYPE_OUTPUT:
626	        {
627	          irqstate_t flags;
628	          uint32_t sample_rate;
629	          uint8_t bpsamp;
630	          uint8_t channels;
631	
632	          sample_rate = caps->ac_controls.hw[0]
633	                      | ((uint32_t)caps->ac_controls.b[3] << 16);
634	          channels = caps->ac_channels;
635	          bpsamp = caps->ac_controls.b[2];
636	
637	          if (bpsamp == 0)
638	            {
639	              bpsamp = BK7258_AUDIO_DEFAULT_BPSAMP;
640	            }
641	
642	          if (sample_rate == 0)
643	            {
644	              sample_rate = BK7258_AUDIO_DEFAULT_SAMPLE_RATE;
645	            }
646	
647	          if (channels == 0)
648	            {
649	              channels = BK7258_AUDIO_DEFAULT_CHANNELS;
650	            }
651	
652	          if (bpsamp != 16)
653	            {
654	              AUD_ERR("only S16_LE supported (asked for %u)", bpsamp);
655	              return -EINVAL;
656	            }
657	
658	          flags = spin_lock_irqsave(&priv->lock);
659	          if (priv->closing)
660	            {
661	              spin_unlock_irqrestore(&priv->lock, flags);
662	              return -ESHUTDOWN;
663	            }
664	
665	          /* Keep a fault latched through hardware teardown and every error
666	           * DEQUEUE.  A persistent runtime fault additionally requires stop
667	           * to have closed the refill gate before OUTPUT configure recovers
668	           * it.
669	           */
670	
671	          if (priv->faulted &&
672	              (priv->fault_pending || dq_peek(&priv->failq) != NULL))
673	            {
674	              spin_unlock_irqrestore(&priv->lock, flags);
675	              return -EBUSY;
676	            }
677	
678	          if (priv->faulted && !priv->recover_after_fault &&
679	              !priv->stopping)
680	            {
681	              int error = priv->dma_error < 0 ? priv->dma_error : -EIO;
682	              spin_unlock_irqrestore(&priv->lock, flags);
683	              return error;
684	            }
685	
686	          priv->sample_rate = sample_rate;
687	          priv->channels = channels;
688	          priv->bpsamp = bpsamp;
689	
690	          /* Successful OUTPUT configure reopens a normal stop/shutdown or a
691	           * fully drained persistent-fault teardown.
692	           */
693	
694	          priv->stopping = false;
695	          priv->faulted = false;
696	          priv->recover_after_fault = false;
697	          priv->complete_pending = false;
698	          priv->final_seen = false;
699	          priv->underrun_pending = false;
700	          priv->dma_error = OK;
701	
702	          spin_unlock_irqrestore(&priv->lock, flags);
703	
704	          AUD_INFO("configure OUTPUT rate=%lu ch=%u bps=%u",
705	                   (unsigned long)sample_rate, channels, bpsamp);
706	        }
707	        break;
708	
709	      case AUDIO_TYPE_FEATURE:
710	        {
711	          irqstate_t flags;
712	          int ret = OK;
713	
714	          flags = spin_lock_irqsave(&priv->lock);
715	          switch (caps->ac_format.hw)
716	            {
717	              case AUDIO_FU_VOLUME:
718	                {
719	                  uint16_t v = caps->ac_controls.hw[0];
720	                  if (v > 100)
721	                    {
722	                      v = 100;
723	                    }
724	
725	                  priv->volume = (uint8_t)v;
726	                }
727	                break;
728	
729	              case AUDIO_FU_MUTE:
730	                priv->mute = caps->ac_controls.b[0] != 0;
731	                break;
732	
733	              default:
734	                spin_unlock_irqrestore(&priv->lock, flags);
735	                return -EINVAL;
736	            }
737	
738	          /* Always cache feature settings, but touch hardware only for a
739	           * healthy running stream.  The check and bounded register update
740	           * share the fault-state lock so a worker mute cannot be undone by
741	           * a concurrent feature configure.
742	           */
743	
744	          if (priv->configured && priv->dac_running && !priv->closing &&
745	              !priv->stopping && !priv->faulted && !priv->fault_pending)
746	            {
747	              ret = bk7258_apply_volume(priv);
748	              if (ret < 0)
749	                {
750	                  /* An analog SPI failure leaves the DAC mute state
751	                   * unknown.  Fail closed: stop accepting/advancing buffers
752	                   * immediately and let LPWORK turn off DMA, DAC and PA.
753	                   * Keep the original register error visible to the ioctl.
754	                   */
755	
756	                  bk7258_fault_locked(priv, ret, false);
757	                  bk7258_schedule_worker_locked(priv);
758	                }
759	            }
760	
761	          spin_unlock_irqrestore(&priv->lock, flags);
762	          return ret;
763	        }
764	
765	      default:
766	        return -ENOSYS;
767	    }
768	
769	  return OK;
770	}
