370	static inline int audio_getnstate(FAR struct audio_upperhalf_s *upper,
371	                                  FAR struct audio_openpriv_s *cur)
372	{
373	  FAR struct audio_openpriv_s *priv;
374	  int nstate = AUDIO_STATE_OPEN;
375	  irqstate_t flags;
376	
377	  flags = spin_lock_irqsave(&upper->spinlock);
378	  for (priv = upper->head; priv != NULL; priv = priv->flink)
379	    {
