169	/****************************************************************************
170	 * Public Functions
171	 ****************************************************************************/
172	
173	int bk7258_adc_configure(const struct bk7258_adc_cfg_s *cfg)
174	{
175	  irqstate_t flags;
176	  uint32_t v;
177	  int ret;
178	
179	  if (cfg == NULL)
180	    {
181	      return -EINVAL;
182	    }
183	
184	  ret = bk7258_aud_subsystem_init();
185	  if (ret < 0)
186	    {
187	      return ret;
188	    }
189	
190	  g_bk7258_adc_use_apll = cfg->use_apll;
191	
192	  /* Clock select — identical to the DAC configure() clock block; the audio
193	   * clock mux is shared between the DAC and ADC paths.
194	   */
195	
196	  if (cfg->use_apll)
197	    {
198	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
199	                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
200	                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
201	                          UINT32_C(1) << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT);
202	
203	      ret = bk7258_apll_program(BK7258_APLL_CAL_VAL_48K);
204	      if (ret < 0)
205	        {
206	          return ret;
207	        }
208	
209	      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
210	      v |= AUD_AUDIO_CFG_APLL_SEL;
211	      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
212	
213	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE2,
214	                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT,
215	                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT);
216	    }
217	  else
218	    {
219	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
220	                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
221	                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
222	                          0u);
223	
224	      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
225	      v &= ~AUD_AUDIO_CFG_APLL_SEL;
226	      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
227	    }
228	
229	  /* Analog MIC preamp enable.  On BK7258 only micen (ana_reg19[28]) is wired;
230	   * AVDK's mic2_en is a no-op, so dual-MIC shares this one bit.  Order matches
231	   * aud_adc_driver.c: micen -> biases -> reset pulse.
232	   */
233	
234	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG19,
235	                           ANA_REG19_MICEN_BIT, 0x1u, 1);
236	  if (ret < 0)
237	    {
238	      return ret;
239	    }
240	
241	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG18,
242	                           ANA_REG18_ENADCBias_BIT, 0x1u, 1);
243	  if (ret < 0)
244	    {
245	      return ret;
246	    }
247	
248	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG18,
249	                           ANA_REG18_ENMICBias_BIT, 0x1u, 1);
250	  if (ret < 0)
251	    {
252	      return ret;
253	    }
254	
255	  /* MIC reset pulse after parameter config (aud_adc_driver.c:104..106). */
256	
257	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG19,
258	                           ANA_REG19_MIC_RST_BIT, 0x1u, 1);
259	  if (ret < 0)
260	    {
261	      return ret;
262	    }
263	
264	  up_mdelay(10);
265	
266	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG19,
267	                           ANA_REG19_MIC_RST_BIT, 0x1u, 0);
268	  if (ret < 0)
269	    {
270	      return ret;
271	    }
272	
273	  /* Digital path: gain, sample edge, HPF bypass. */
274	
275	  flags = spin_lock_irqsave(&g_bk7258_adc_lock);
276	  v = getreg32(BK7258_AUD_ADC_CONFIG0);
277	  v &= ~(AUD_ADC_CFG0_GAIN_MASK | AUD_ADC_CFG0_SAMP_EDGE
278	         | AUD_ADC_CFG0_HPF1_BYPASS | AUD_ADC_CFG0_HPF2_BYPASS);
279	  v |= ((uint32_t)(cfg->gain & 0x3Fu) << AUD_ADC_CFG0_GAIN_SHIFT);
280	  if (cfg->samp_edge)
281	    {
282	      v |= AUD_ADC_CFG0_SAMP_EDGE;
283	    }
284	  v |= AUD_ADC_CFG0_HPF1_BYPASS | AUD_ADC_CFG0_HPF2_BYPASS;
285	  putreg32(v, BK7258_AUD_ADC_CONFIG0);
286	  spin_unlock_irqrestore(&g_bk7258_adc_lock, flags);
287	
288	  /* Sample-rate divider. */
289	
290	  ret = bk7258_adc_set_sample_rate(cfg->samp_rate);
291	  if (ret < 0)
292	    {
293	      return ret;
294	    }
295	
296	  bk7258_adc_set_adcl_wr_threshold(BK7258_ADC_ADCL_WR_TH_DEFAULT);
297	
298	  g_bk7258_adc_configured = true;
299	  return OK;
300	}
301	
302	int bk7258_adc_set_sample_rate(uint32_t samp_rate)
303	{
304	  uint32_t sr_code;
305	  bool     apll_44k_family = false;
306	  uint32_t v;
307	  int ret;
308	
309	  switch (samp_rate)
310	    {
311	      case 8000:
312	        sr_code = AUD_SAMP_RATE_8K;
313	        break;
314	
315	      case 16000:
316	        sr_code = AUD_SAMP_RATE_16K;
317	        break;
318	
319	      case 44100:
320	        sr_code = AUD_SAMP_RATE_44_1K;
321	        apll_44k_family = true;
322	        break;
323	
324	      case 48000:
325	        sr_code = AUD_SAMP_RATE_48K;
326	        break;
327	
328	      default:
329	        auderr("BK7258: unsupported ADC sample rate %lu\n",
330	               (unsigned long)samp_rate);
331	        return -EINVAL;
332	    }
333	
334	  /* On APLL, the 44.1k family requires a different cal value. */
335	
336	  if (g_bk7258_adc_use_apll)
337	    {
338	      ret = bk7258_apll_program(apll_44k_family
339	                                    ? BK7258_APLL_CAL_VAL_44_1K
340	                                    : BK7258_APLL_CAL_VAL_48K);
341	      if (ret < 0)
342	        {
343	          return ret;
344	        }
345	    }
346	
347	  /* Standard rates use the auto divider: clear adc_fracmod_manual, then set
348	   * samp_rate_ADC [1:0] (distinct from samp_rate_DAC [7:6]).
349	   */
350	
351	  v = getreg32(BK7258_AUD_EXTEND_CFG);
352	  v &= ~AUD_EXT_CFG_ADC_FRACMOD_MAN;
353	  putreg32(v, BK7258_AUD_EXTEND_CFG);
354	
355	  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
356	  v &= ~AUD_AUDIO_CFG_SAMP_RATE_ADC_MASK;
357	  v |= (sr_code << AUD_AUDIO_CFG_SAMP_RATE_ADC_SHIFT)
358	       & AUD_AUDIO_CFG_SAMP_RATE_ADC_MASK;
359	  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
360	
361	  return OK;
362	}
