549	static int bk7258_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
550	                          FAR struct audio_caps_s *caps)
551	{
552	  (void)dev;
553	  (void)type;
554	
555	  DEBUGASSERT(caps->ac_len >= sizeof(struct audio_caps_s));
556	
557	  caps->ac_format.hw   = 0;
558	  caps->ac_controls.w  = 0;
559	
560	  switch (caps->ac_type)
561	    {
562	      case AUDIO_TYPE_QUERY:
563	        caps->ac_channels = AUDIO_CHANNELS_RANGE(1, 2);
564	        switch (caps->ac_subtype)
565	          {
566	            case AUDIO_TYPE_QUERY:
567	              caps->ac_controls.b[0] = AUDIO_TYPE_OUTPUT | AUDIO_TYPE_FEATURE;
568	              caps->ac_format.hw     = 1 << (AUDIO_FMT_PCM - 1);
569	              break;
570	
571	            case AUDIO_FMT_PCM:
572	              caps->ac_controls.b[0] = AUDIO_SUBFMT_PCM_S16_LE;
573	              break;
574	
575	            default:
576	              caps->ac_controls.b[0] = AUDIO_SUBFMT_END;
577	              break;
578	          }
579	        break;
580	
581	      case AUDIO_TYPE_OUTPUT:
582	        caps->ac_channels = AUDIO_CHANNELS_RANGE(1, 2);
583	        if (caps->ac_subtype == AUDIO_TYPE_QUERY)
584	          {
585	            caps->ac_controls.hw[0] = AUDIO_SAMP_RATE_8K
586	                                    | AUDIO_SAMP_RATE_16K
587	                                    | AUDIO_SAMP_RATE_44K
588	                                    | AUDIO_SAMP_RATE_48K;
589	          }
590	        break;
591	
592	      case AUDIO_TYPE_FEATURE:
593	        if (caps->ac_subtype == AUDIO_TYPE_QUERY)
594	          {
595	            caps->ac_controls.hw[0] = AUDIO_FU_VOLUME | AUDIO_FU_MUTE;
596	          }
597	        break;
598	
599	      default:
600	        caps->ac_subtype  = 0;
601	        caps->ac_channels = 0;
602	        break;
603	    }
604	
605	  return caps->ac_len;
606	}
