209	static int ensure_scratch_capacity(audio_capture_t* cap, size_t need)
210	{
211	    if (cap->scratch_size >= need) {
212	        return 0;
213	    }
214	
215	    unsigned char* scratch = realloc(cap->scratch, need);
216	    if (!scratch) {
217	        return -ENOMEM;
218	    }
219	
220	    cap->scratch = scratch;
221	    cap->scratch_size = need;
222	    return 0;
