261	static void downmix_interleaved_s16_to_mono(audio_capture_t* cap,
262	    void* out_buf, const void* in_buf, size_t frames)
263	{
264	    int16_t* out = out_buf;
265	    const int16_t* in = in_buf;
266	
267	    for (size_t i = 0; i < frames; i++) {
268	        int32_t mixed = 0;
269	
270	        for (unsigned int ch = 0; ch < cap->hw_channels; ch++) {
271	            mixed += in[i * cap->hw_channels + ch];
272	        }
273	
274	        out[i] = (int16_t)(mixed / (int32_t)cap->hw_channels);
275	    }
276	}
