278	static int open_alsa_capture(audio_capture_t* cap, const char* dev_path,
279	    unsigned int sample_rate, unsigned int channels,
280	    unsigned int bits_per_sample)
281	{
282	    const char* alsa_name = resolve_alsa_name(dev_path);
283	    snd_pcm_format_t format = capture_format_from_bits(bits_per_sample);
284	    unsigned int attempts[2];
285	    int attempt_count = 0;
286	    int last_ret = -ENODEV;
287	
288	    if ((int)format < 0) {
289	        return -ENOTSUP;
290	    }
291	
292	    attempts[attempt_count++] = channels;
293	    if (channels == 1) {
294	        attempts[attempt_count++] = 3;
295	    }
296	
297	    for (int i = 0; i < attempt_count; i++) {
298	        snd_pcm_t* pcm = NULL;
299	        unsigned int hw_channels = attempts[i];
300	        int ret = snd_vela_pcm_open(&pcm, alsa_name,
301	            SND_VELA_PCM_STREAM_CAPTURE, 0);
302	
303	        if (ret < 0) {
304	            last_ret = ret;
305	            continue;
306	        }
307	
308	        ret = configure_alsa_capture(pcm, format, sample_rate, hw_channels);
309	        if (ret < 0) {
310	            snd_vela_pcm_close(pcm);
311	            last_ret = ret;
312	            continue;
313	        }
314	
315	        cap->backend = AUDIO_CAPTURE_BACKEND_ALSA;
316	        cap->handle.pcm = pcm;
317	        cap->bits_per_sample = bits_per_sample;
318	        cap->requested_channels = channels;
319	        cap->hw_channels = hw_channels;
320	        cap->out_frame_bytes = (bits_per_sample / 8) * channels;
321	        cap->hw_frame_bytes = snd_vela_pcm_frames_to_bytes(pcm, 1);
322	
323	        syslog(LOG_INFO,
324	            "[%s] opened direct ALSA capture (%s, %uHz, req=%uch, hw=%uch, %ubit)\n",
325	            TAG, alsa_name, sample_rate, channels, hw_channels,
326	            bits_per_sample);
327	        return 0;
328	    }
329	
330	    return last_ret;
331	}
