**Lower-half `read` callback** (non-blocking, returns immediately):
```c
static int bk7258_capture_read(FAR struct audio_lowerhalf_s *dev,
                               FAR char *buffer, size_t buflen)
{
  FAR struct bk7258_capture_s *priv = (FAR struct bk7258_capture_s *)dev;
  FAR int16_t *dst = (FAR int16_t *)buffer;
  size_t nsamples = buflen / 2;
  size_t i;
  irqstate_t flags;

  if ((buflen & 1u) != 0u)
    return -EINVAL;

  flags = spin_lock_irqsave(&priv->lock);
  if (!priv->running)
    {
      spin_unlock_irqrestore(&priv->lock, flags);
      return -EPIPE;   /* stream stopped */
    }
  spin_unlock_irqrestore(&priv->lock, flags);

  for (i = 0; i < nsamples; i++)
    {
      uint32_t word;

      if (bk7258_adc_fifo_empty())
        break;

      word = bk7258_adc_fifo_read();
      dst[i] = (int16_t)(word & 0xFFFFu);
    }

  if (i == 0)
    return -EAGAIN;

  return (int)(i * 2);
}
```

