```c
static int bk7258_capture_configure(FAR struct audio_lowerhalf_s *dev,
                                    FAR const struct audio_caps_s *caps)
{
  FAR struct bk7258_capture_s *priv = (FAR struct bk7258_capture_s *)dev;
  struct bk7258_adc_cfg_s adc_cfg;
  uint32_t sample_rate;
  uint8_t bpsamp;
  uint8_t channels;
  irqstate_t flags;
  int ret;

  if (caps->ac_type != AUDIO_TYPE_INPUT)
    {
      return -EINVAL;  /* capture device only */
    }

  sample_rate = caps->ac_controls.hw[0] | ((uint32_t)caps->ac_controls.b[3] << 16);
  channels = caps->ac_channels;
  bpsamp = caps->ac_controls.b[2];

  if (sample_rate == 0) sample_rate = BK7258_AUDIO_DEFAULT_SAMPLE_RATE;
  if (channels == 0) channels = 1;
  if (bpsamp == 0) bpsamp = BK7258_AUDIO_DEFAULT_BPSAMP;

  if (bpsamp != 16)
    {
      AUD_ERR("only S16_LE supported (asked for %u)", bpsamp);
      return -EINVAL;
    }

  if (channels != 1)
    {
      AUD_ERR("only mono supported (asked for %u)", channels);
      return -EINVAL;
    }

  flags = spin_lock_irqsave(&priv->lock);
  if (priv->closing)
    {
      spin_unlock_irqrestore(&priv->lock, flags);
      return -ESHUTDOWN;
    }
  priv->sample_rate = sample_rate;
  priv->channels = channels;
  priv->bpsamp = bpsamp;
  spin_unlock_irqrestore(&priv->lock, flags);

  /* Program the ADC block for single-mic capture. */
  adc_cfg.samp_rate = sample_rate;
  adc_cfg.channel   = BK7258_ADC_CHL_L;   /* single analog MIC on left input */
  adc_cfg.gain      = BK7258_AUDIO_ADC_DEFAULT_GAIN;
  adc_cfg.samp_edge = false;
  adc_cfg.use_apll  = true;

  ret = bk7258_adc_configure(&adc_cfg);
  if (ret < 0)
    {
      AUD_ERR("adc_configure failed: %d", ret);
      return ret;
    }

  priv->configured = true;
  return OK;
}
```

