264	static int bk7258_capture_start(FAR struct audio_lowerhalf_s *dev)
265	{
266	  FAR struct bk7258_capture_s *priv = (FAR struct bk7258_capture_s *)dev;
267	  irqstate_t flags;
268	
269	  flags = spin_lock_irqsave(&priv->lock);
270	  if (priv->closing)
271	    {
272	      spin_unlock_irqrestore(&priv->lock, flags);
273	      return -ESHUTDOWN;
274	    }
275	
276	  if (!priv->configured)
277	    {
278	      spin_unlock_irqrestore(&priv->lock, flags);
279	      return -EINVAL;
280	    }
281	
282	  if (priv->running)
283	    {
284	      spin_unlock_irqrestore(&priv->lock, flags);
285	      return OK;
286	    }
287	
288	  priv->running = true;
289	  spin_unlock_irqrestore(&priv->lock, flags);
290	
291	  /* Enable the ADC clock and data path.  From here the FIFO fills at the
292	   * configured sample rate; the read callback drains it.
293	   */
294	
295	  bk7258_adc_start();
296	  return OK;
297	}
