355	static int bk7258_capture_read(FAR struct audio_lowerhalf_s *dev,
356	                               FAR char *buffer, size_t buflen)
357	{
358	  FAR struct bk7258_capture_s *priv = (FAR struct bk7258_capture_s *)dev;
359	  FAR int16_t *dst = (FAR int16_t *)buffer;
360	  size_t nsamples = buflen / sizeof(int16_t);
361	  size_t i;
362	  irqstate_t flags;
363	
364	  if ((buflen & 1u) != 0u || nsamples == 0)
365	    {
366	      return -EINVAL;
367	    }
368	
369	  flags = spin_lock_irqsave(&priv->lock);
370	  if (!priv->running)
371	    {
372	      spin_unlock_irqrestore(&priv->lock, flags);
373	      return -EPIPE;
374	    }
375	
376	  spin_unlock_irqrestore(&priv->lock, flags);
377	
378	  for (i = 0; i < nsamples; i++)
379	    {
380	      uint32_t word;
381	
382	      if (bk7258_adc_fifo_empty())
383	        {
384	          break;
385	        }
386	
387	      word   = bk7258_adc_fifo_read();
388	      dst[i] = (int16_t)(word & UINT32_C(0xFFFF));
389	    }
390	
391	  if (i == 0)
392	    {
393	      return -EAGAIN;
394	    }
395	
396	  return (int)(i * sizeof(int16_t));
397	}
